'use strict';
const view=document.querySelector('#view');let courses=[],filter='全部課程',query='',progress={};
try{progress=JSON.parse(localStorage.getItem('compass-progress-v1')||'{}');if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={}}catch{progress={}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('compass-progress-v1',JSON.stringify(progress));return true}catch{return false}}
function home(){document.querySelector('#crumb').textContent='所有課程';const done=courses.filter(c=>progress[c.id]?.complete).length;view.innerHTML=`<section class="hero"><div><div class="eyebrow">LESS, BUT BETTER LEARNING</div><h1>每一門課，<br>都有清楚的<em>學習方向。</em></h1><p class="intro">把厚厚的講義，整理成讀得懂、記得住的知識。<br>從核心觀念出發，用小測驗確認自己真的學會。</p></div><div class="hero-art" aria-hidden="true">✳</div></section><div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><b>${courses.length.toString().padStart(2,'0')}</b><small>收錄課程</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><b>${done.toString().padStart(2,'0')}</b><small>已完成課程</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><b>${courses.reduce((n,c)=>n+c.minutes,0)}</b><small>分鐘・預估總閱讀</small></div></div></div><div class="section-head"><h2>探索你的下一門課</h2><span>理解觀念 → 閱讀實例 → 主動回想</span></div><div class="toolbar"><div class="filters" role="group" aria-label="課程分類">${['全部課程',...new Set(courses.map(c=>c.category))].map(t=>`<button class="chip ${filter===t?'selected':''}" aria-pressed="${filter===t}" data-filter="${esc(t)}">${esc(t)}</button>`).join('')}</div><input class="search" type="search" placeholder="搜尋課程、觀念或關鍵字…" aria-label="搜尋課程" value="${esc(query)}"></div><div class="grid" id="cards" aria-live="polite"></div><div class="tip"><span aria-hidden="true">✧</span><div><strong>不只是讀完，而是真的學會。</strong><p>讀完一個觀念後，先合上筆記，再用自己的話解釋一次。</p></div><a href="#guide">看看學習指南 ↗</a></div><p class="notice">目前收錄 1 門講義整理、2 門原創示範。進度儲存在此瀏覽器，沒有跨裝置同步。</p>`;renderCards();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;home()});document.querySelector('.search').oninput=e=>{query=e.target.value;renderCards()}}
function renderCards(){const found=courses.filter(c=>(filter==='全部課程'||c.category===filter)&&JSON.stringify(c).toLowerCase().includes(query.trim().toLowerCase()));document.querySelector('#cards').innerHTML=found.length?found.map((c,i)=>`<a class="card" href="#course/${c.id}"><div class="card-art"><span>FIELD NOTES / ${String(courses.indexOf(c)+1).padStart(2,'0')}</span><strong aria-hidden="true">${c.icon}</strong></div><div class="card-body"><span class="tag">${esc(c.category)} · ${esc(c.level)}${c.id!=='agentic-work'?' · 原創示範':''}</span><h3>${esc(c.title)}</h3><p>${esc(c.subtitle)}</p><div class="meta"><span>◷ ${c.minutes} 分鐘</span><span>▤ ${c.concepts.length} 個核心觀念</span></div><div class="card-bottom"><span class="status ${progress[c.id]?.complete?'done':''}">${progress[c.id]?.complete?'✓ 已完成':'○ 尚未完成'}</span><b>${progress[c.id]?.complete?'再次複習':'開始學習'} ↗</b></div></div></a>`).join(''):'<div class="empty">找不到符合的課程。試試其他關鍵字或分類。</div>'}
function lesson(c){document.querySelector('#crumb').textContent=c.title;view.innerHTML=`<a class="back" href="#">← 回到所有課程</a><div class="lesson-header"><span class="eyebrow">${esc(c.category)} / ${c.minutes} MIN READ</span><h1>${esc(c.title)}</h1><p class="intro">${esc(c.subtitle)}</p><p class="source">來源：${esc(c.source)}</p></div><div class="lesson-layout"><div><section class="panel"><h2>這堂課，你會學到</h2><ul>${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></section>${c.concepts.map((x,i)=>`<section class="panel" id="concept-${i}"><span class="eyebrow">CONCEPT ${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><div class="example">${esc(x.example)}</div></section>`).join('')}<section class="panel"><h2>容易混淆的地方</h2><p>${esc(c.pitfall)}</p><h3>換你試試看</h3><p>${esc(c.exercise)}</p></section><section class="panel"><h2>用兩題，檢查理解</h2><p class="notice">答完後查看解析；答錯可以重新嘗試。</p><form id="quiz">${c.quiz.map((q,i)=>`<div class="question"><fieldset><legend>${i+1}. ${esc(q.question)}</legend>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" required> ${esc(o)}</label>`).join('')}</fieldset><div id="feedback-${i}"></div></div>`).join('')}<button class="primary" type="submit">檢查答案</button><div id="quiz-result" role="status"></div></form></section></div><aside class="panel lesson-side"><h2>學習路線</h2><ol>${c.concepts.map((x,i)=>`<li><a href="#concept-${i}" data-anchor="concept-${i}">${esc(x.title)}</a></li>`).join('')}</ol><button id="complete" class="primary">${progress[c.id]?.complete?'取消完成標記':'標記本課完成'}</button><p class="notice" id="save-message">完成標記代表你的自評，可隨時取消。</p></aside></div>`;document.querySelectorAll('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.anchor).scrollIntoView({behavior:'smooth'})});document.querySelector('#complete').onclick=()=>{progress[c.id]={...progress[c.id],complete:!progress[c.id]?.complete};const ok=save();lesson(c);if(!ok)document.querySelector('#save-message').textContent='瀏覽器無法儲存；進度僅保留到這次頁面關閉。'};document.querySelector('#quiz').onsubmit=e=>{e.preventDefault();let correct=0;const data=new FormData(e.target);c.quiz.forEach((q,i)=>{const yes=Number(data.get('q'+i))===q.answer;if(yes)correct++;document.getElementById('feedback-'+i).innerHTML=`<p class="feedback ${yes?'':'error'}">${yes?'✓ 答對了':'再想一想'}：${esc(q.explanation)} 正確答案：${esc(q.options[q.answer])}</p>`});document.querySelector('#quiz-result').textContent=`本次答對 ${correct} / ${c.quiz.length} 題。${correct===c.quiz.length?'可以試著不看筆記，自己說明一次。':'回到觀念區複習，再試一次。'}`}}
function guide(){document.querySelector('#crumb').textContent='使用與新增指南';view.innerHTML=`<a class="back" href="#">← 回到所有課程</a><div class="eyebrow">LEARNING PLAYBOOK</div><h1>讓下一門課，<br>也有清楚的整理方式。</h1><section class="panel"><h2>三步驟學習</h2><ol><li>先看學習目標，再閱讀核心觀念與例子。</li><li>不看筆記，完成「換你試試看」與測驗。</li><li>依解析補足觀念，自評完成後標記；隔一段時間再複習。</li></ol></section><section class="panel"><h2>請 AI 幫忙新增課程</h2><p>這個網站採用共用模板。開發時先讀專案根目錄的 <code>AGENTS.md</code>，複製 <code>templates/course.json</code>，完成資料後加入 <code>dist/data/courses.json</code>。</p><pre>請先閱讀 AGENTS.md。依照我提供的講義，新增一門課程：\n1. 列出三個學習目標與三個核心觀念。\n2. 每個觀念附一個例子，並提供兩題有解析的測驗。\n3. 記錄來源與頁碼，缺資料時標記待確認，不要猜測。\n4. 執行驗證，確認列表、課程頁與測驗正常。</pre><p>目前網站沒有上傳檔案或自動 AI 摘要功能。新增內容需要透過 AI 開發工具修改專案資料，再重新部署。</p></section><section class="panel"><h2>資料與隱私</h2><p>課程內容是靜態公開資料。進度只存放在瀏覽器 localStorage；清除網站資料後會重設。請勿把同學個資、私人筆記或未授權完整教材放進公開 Repository。</p><button id="reset" class="secondary">清除這台瀏覽器的學習進度</button><p id="reset-status" role="status"></p></section>`;document.querySelector('#reset').onclick=()=>{progress={};const ok=save();document.querySelector('#reset-status').textContent=ok?'學習進度已清除。':'已清除本次進度，但瀏覽器儲存不可用。'}}
function route(){const h=location.hash;if(h==='#guide')guide();else if(h.startsWith('#course/')){const c=courses.find(c=>c.id===h.slice(8));if(c)lesson(c);else view.innerHTML='<h1>找不到這門課</h1><a href="#">回到所有課程</a>'}else home();window.scrollTo(0,0)}
fetch('data/courses.json').then(r=>{if(!r.ok)throw Error('資料讀取失敗');return r.json()}).then(data=>{courses=data;document.querySelector('#nav-count').textContent=courses.length;route();window.addEventListener('hashchange',route)}).catch(()=>{view.innerHTML='<h1>課程載入失敗</h1><p>請透過 HTTP 伺服器開啟網站，或重新整理再試一次。</p><button class="primary" onclick="location.reload()">重新載入</button>'});
